import json, re, collections, pathlib
man={json.loads(l)['instance_id']: json.loads(l) for l in open('corpus/manifest.jsonl')}
recs=[json.loads(l) for l in open('corpus/records.jsonl')]
scratch=pathlib.Path('/tmp/diag/run2/scratch')
line_re=re.compile(r'^(\S+::\S+)\s+(PASSED|FAILED|ERROR|SKIPPED|XFAIL|XPASS|XFAILED)\b')
def norm(n): return '.'.join(n.split('::')[1:])
hits=collections.Counter(); examples=[]
for r in recs:
    rid=r['record_id']; inst=man[r['instance_id']]
    p=scratch/rid/'pytest.log'
    log=p.read_text(errors='replace') if p.exists() else ''
    st={}
    for line in log.splitlines():
        m=line_re.match(line.strip())
        if m: st[m.group(1)]=m.group(2)
    if not st: continue
    req=list(inst['fail_to_pass'])+list(inst['pass_to_pass'])
    reqnorm=collections.defaultdict(list)
    for n in req: reqnorm[norm(n)].append(n)
    # collisions among reported node ids with same normalized name but different status
    byn=collections.defaultdict(dict)
    for full,s in st.items(): byn[norm(full)][full]=s
    for k,d in byn.items():
        if len(d)>1 and len(set(d.values()))>1 and k in reqnorm:
            hits[rid]+=1
            examples.append((rid,k,d,reqnorm[k]))
print('records with status-conflicting same-normalized-name node ids that are required:', len(hits))
for rid,k,d,req in examples[:15]:
    print(rid, '|', k, '|', d, '| required:', req)
EOF

